mapper.select:
SELECT DISTINCT attr_invoke.id, attr_invoke.cientity_id AS ciEntityId, attr_invoke.attr_id AS attrId, attr_invoke.type, attr_invoke.invoke_id AS invokeId FROM cmdb_attr_invoke attr_invoke JOIN cmdb_attr_invoke device ON device.cientity_id = attr_invoke.cientity_id AND device.attr_id = attr_invoke.attr_id AND device.type = 'device'
WHERE device.id IN
#{attrInvokeId}
AND device.attr_id IN
#{attrId}
WHERE 1 = 0

mapper.delete:
DELETE FROM `cmdb_attr_invoke`
WHERE cientity_id = #{ciEntityId}
  AND attr_id = #{attrId}
